const readStorage=(key,def)=>{try{const v=JSON.parse(localStorage.getItem('decentclone_'+key));return v??def;}catch{return def;}};
const saveStorage=(key,v)=>{try{localStorage.setItem('decentclone_'+key,JSON.stringify(v));}catch{}};
const state = {currentBook:readStorage('book','pdt'), lists:{},listPromises:{}, details:{},ingredientLists:{},fav:readStorage('fav',[]),made:readStorage('made',[]),bar:readStorage('bar',[]),theme:readStorage('theme','light'),menu:false,qty:1,visible:36,sort:'popular',search:'',scaleIndex:0,modal:false,token:0,versionIndex:0,spiritIndex:null};
